import sys

def main():
    lines = sys.stdin.read().split()
    if len(lines) < 2:
        return
    t, p = lines[0], lines[1]
    n, m = len(t), len(p)
    if m > n:
        print(0)
        return

    base = 311
    mod = 10**9 + 7

    h_t = [0] * (n + 1)
    p_pow = [1] * (n + 1)
    for i in range(n):
        h_t[i + 1] = (h_t[i] * base + ord(t[i])) % mod
        p_pow[i + 1] = (p_pow[i] * base) % mod

    h_p = 0
    for c in p:
        h_p = (h_p * base + ord(c)) % mod

    def get_hash(l, r):
        val = (h_t[r] - h_t[l - 1] * p_pow[r - l + 1]) % mod
        return (val + mod) % mod

    matches = []
    for i in range(1, n - m + 2):
        if get_hash(i, i + m - 1) == h_p:
            matches.append(str(i))

    print(len(matches))
    if matches:
        print(" ".join(matches))

